    const int Z = 100;
    const int N = Z * Z;
    const int M = Z * Z * Z * 3;
    vector<int> px(N), py(N), head(N, -1), to(M), ct(M), w(M), nt(M);
    vector<int> dist(N), visited(N), parent(N), edge_id(N);
    int total_edges = 0;

    auto add_edge = [&](int u, int v, int flow, int cost) {
        to[total_edges] = v; ct[total_edges] = cost; w[total_edges] = flow; nt[total_edges] = head[u]; head[u] = total_edges++;
        to[total_edges] = u; ct[total_edges] = -cost; w[total_edges] = 0; nt[total_edges] = head[v]; head[v] = total_edges++;
    };

    auto initialize = [&]() {
        fill(head.begin(), head.end(), -1);
        total_edges = 0;
    };

    auto spfa = [&](int s, int t) {
        queue<int> q;
        fill(dist.begin(), dist.end(), INT_MAX);
        fill(visited.begin(), visited.end(), 0);
        fill(parent.begin(), parent.end(), -1);
        dist[s] = 0;
        q.push(s);
        while (!q.empty()) {
            int u = q.front(); q.pop();
