            for (int i = t; i != s; i = parent[i]) {
                w[edge_id[i]] -= flow;
                w[edge_id[i] ^ 1] += flow;
            }
            total_cost += dist[t] * flow;
            total_flow += flow;
        }
        return total_cost;
    };

