import java.util.*;
import java.io.*;

public class Main {

    static class Edge {
        int to, cost, flow, rev;

        public Edge(int to, int cost, int flow, int rev) {
            this.to = to;
            this.cost = cost;
            this.flow = flow;
            this.rev = rev;
        }
    }

    static final int Z = 100;
    static final int N = Z * Z;
    static final int M = Z * Z * Z * 3;

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int n = Integer.parseInt(st.nextToken());
        int m = Integer.parseInt(st.nextToken());
        int k = Integer.parseInt(st.nextToken());
        int c = Integer.parseInt(st.nextToken());
        int d = Integer.parseInt(st.nextToken());

        List<List<Edge>> graph = new ArrayList<>();
        for (int i = 0; i < N + 2; i++) {
            graph.add(new ArrayList<>());
        }
        int s = 0;
        int t = n * 100 + 1;

        // Add edge function
        BiConsumer<Integer, Edge> addEdge = (u, e) -> {
            graph.get(u).add(e);
        };

        // Helper to add edges
        Runnable initialize = () -> {
            for (List<Edge> edges : graph) {
                edges.clear();
            }
        };

        // Add edges method
        void addEdge(int u, int v, int flow, int cost) {
            graph.get(u).add(new Edge(v, cost, flow, graph.get(v).size()));
            graph.get(v).add(new Edge(u, -cost, 0, graph.get(u).size() - 1));
        }

        // Implement min-cost max-flow (Successive shortest path with SPFA)
        int maxFlowMinCost(int s, int t) {
            int totalFlow = 0;
            int totalCost = 0;
            int[] dist = new int[N + 2];
            int[] parent = new int[N + 2];
            int[] parentEdge = new int[N + 2];

            while (true) {
                Arrays.fill(dist, Integer.MAX_VALUE);
                dist[s] = 0;
                boolean[] inQueue = new boolean[N + 2];
                Queue<Integer> q = new LinkedList<>();
                q.offer(s);
                while (!q.isEmpty()) {
                    int u = q.poll();
                    inQueue[u] = false;
                    for (int i = 0; i < graph.get(u).size(); i++) {
                        Edge e = graph.get(u).get(i);
                        if (e.flow > 0 && dist[u] + e.cost < dist[e.to]) {
                            dist[e.to] = dist[u] + e.cost;
                            parent[e.to] = u;
                            parentEdge[e.to] = i;
                            if (!inQueue[e.to]) {
                                inQueue[e.to] = true;
                                q.offer(e.to);
                            }
                        }
                    }
                }
                if (dist[t] == Integer.MAX_VALUE) break;
                int flow = Integer.MAX_VALUE;
                for (int u = t; u != s; u = parent[u]) {
                    flow = Math.min(flow, graph.get(parent[u]).get(parentEdge[u]).flow);
                }
                for (int u = t; u != s; u = parent[u]) {
                    Edge e = graph.get(parent[u]).get(parentEdge[u]);
                    e.flow -= flow;
                    graph.get(u).get(e.rev).flow += flow;
                }
                totalCost += dist[t] * flow;
                totalFlow += flow;
            }
            return totalCost;
        }

        initialize.run();
        // Add edges for sink
        for (int i = 1; i <= 100; i++) {
            addEdge.apply(s, new Edge(t, 0, 100, 0));
        }
        // Read stations
        st = new StringTokenizer(br.readLine());
        for (int i = 0; i < k; i++) {
            int v = Integer.parseInt(st.nextToken());
            addEdge.apply(s, new Edge((v - 1) * 100 + 1, 1, 0));
        }
        // Horizontal connections
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j < 100; j++) {
                int fromNode = (i - 1) * 100 + j;
                int toNode = (i - 1) * 100 + j + 1;
                for (int kIter = 1; kIter <= 50; kIter++) {
                    int costVal = c + (kIter * kIter - (kIter - 1) * (kIter - 1)) * d;
                    addEdge.apply(fromNode, new Edge(toNode, costVal, 1));
                }
            }
        }
        // M connections
        for (int i = 0; i < m; i++) {
            st = new StringTokenizer(br.readLine());
            int u = Integer.parseInt(st.nextToken());
            int v = Integer.parseInt(st.nextToken());
            for (int j = 1; j < 100; j++) {
                int idx = (u - 1) * 100 + j;
                int idy = (v - 1) * 100 + j + 1;
                for (int kIter = 1; kIter <= 50; kIter++) {
                    int costVal = c + (kIter * kIter - (kIter - 1) * (kIter - 1)) * d;
                    addEdge.apply(idx, new Edge(idy, costVal, 1));
                }
            }
            for (int j = 1; j < 100; j++) {
                int idx = (v - 1) * 100 + j;
                int idy = (u - 1) * 100 + j + 1;
                for (int kIter = 1; kIter <= 50; kIter++) {
                    int costVal = c + (kIter * kIter - (kIter - 1) * (kIter - 1)) * d;
                    addEdge.apply(idx, new Edge(idy, costVal, 1));
                }
            }
        }

        System.out.println(maxFlowMinCost(s, t));
    }
}

